function cloneCategoryDetailDraftState(value) {
  return JSON.parse(JSON.stringify(value));
}

function cloneUnitDetailDraftState(value) {
  return JSON.parse(JSON.stringify(value));
}

function getCategoryDetailValidationMessage(detailDraft, detailEditing) {
  if (!detailDraft || !detailEditing) return null;

  if (detailEditing.kind === "all" && !detailDraft.name.trim()) {
    return "Field cannot be empty";
  }

  if (detailEditing.field === "name" && !detailDraft.name.trim()) {
    return "Field cannot be empty";
  }

  return null;
}

function getUnitDetailValidationMessage(detailDraft, detailEditing) {
  if (!detailDraft || !detailEditing) return null;

  if (detailEditing.kind === "all" && !detailDraft.name.trim()) {
    return "Field cannot be empty";
  }

  if (detailEditing.field === "name" && !detailDraft.name.trim()) {
    return "Field cannot be empty";
  }

  return null;
}

function isSameCategoryDetailEditing(currentEditing, nextEditing) {
  return (
    currentEditing?.kind === nextEditing?.kind &&
    currentEditing?.field === nextEditing?.field
  );
}

function isSameUnitDetailEditing(currentEditing, nextEditing) {
  return (
    currentEditing?.kind === nextEditing?.kind &&
    currentEditing?.field === nextEditing?.field
  );
}

function getConnectedCatalogNamesForUnit(unitName, catalogRows = []) {
  return catalogRows
    .filter((catalog) => (catalog.unit || "Pcs") === unitName)
    .map((catalog) => catalog.name);
}

function getModifierDetailValidationMessage(detailDraft, detailEditing) {
  if (!detailDraft || !detailEditing) return null;

  if (detailEditing.kind === "all" && !detailDraft.name.trim()) {
    return "Field cannot be empty";
  }

  if (detailEditing.kind === "field" && detailEditing.field === "name") {
    if (!detailDraft.name.trim()) {
      return "Field cannot be empty";
    }
  }

  if (detailEditing.kind === "option-row") {
    const option = (detailDraft.options ?? []).find(
      (item) => item.id === detailEditing.optionId
    );
    if (!option?.name?.trim()) {
      return "Field cannot be empty";
    }
    if (
      hasModifierOptionIngredient(option) &&
      !isModifierOptionIngredientQtyValid(option)
    ) {
      return "Qty must be greater than 0 when ingredient is selected";
    }
  }

  if (
    (detailEditing.kind === "all" || detailEditing.kind === "option-row") &&
    getModifierOptionIngredientQtyErrorIds(detailDraft.options ?? []).length
  ) {
    return "Qty must be greater than 0 when ingredient is selected";
  }

  return null;
}

function isSameModifierDetailEditing(currentEditing, nextEditing) {
  if (
    !currentEditing ||
    !nextEditing ||
    currentEditing.kind !== nextEditing.kind
  ) {
    return false;
  }

  if (currentEditing.kind === "all" && nextEditing.kind === "all") {
    return true;
  }

  if (currentEditing.kind === "field" && nextEditing.kind === "field") {
    return currentEditing.field === nextEditing.field;
  }

  if (
    currentEditing.kind === "option-row" &&
    nextEditing.kind === "option-row"
  ) {
    return currentEditing.optionId === nextEditing.optionId;
  }

  return false;
}

function getSellingTimeDaysFromRecord(record) {
  if (Array.isArray(record?.days) && record.days.length) {
    return record.days.filter(Boolean);
  }

  if (Array.isArray(record?.schedule)) {
    return record.schedule
      .filter((day) => day?.enabled)
      .map((day) => day?.label)
      .filter(Boolean);
  }

  return record?.day ? [record.day] : [];
}

function getSellingTimeDayDisplay(record) {
  const dayLabels = getSellingTimeDaysFromRecord(record);
  return dayLabels.length ? dayLabels.join(", ") : "-";
}

function getDefaultSellingTimeSlotsForRecord(recordName, dayLabel) {
  const normalizedName = String(recordName ?? "")
    .trim()
    .toLowerCase();
  const normalizedDayLabel = String(dayLabel ?? "")
    .trim()
    .toLowerCase();

  if (normalizedName === "all day") {
    return [
      { id: `${normalizedDayLabel}-slot-1`, start: "00:00", end: "23:59" },
    ];
  }

  if (normalizedName === "breakfast") {
    return [
      { id: `${normalizedDayLabel}-slot-1`, start: "06:00", end: "11:00" },
    ];
  }

  if (normalizedName === "lunch rush") {
    return [
      { id: `${normalizedDayLabel}-slot-1`, start: "11:00", end: "15:00" },
    ];
  }

  if (normalizedName === "late night") {
    return [
      { id: `${normalizedDayLabel}-slot-1`, start: "21:00", end: "23:59" },
    ];
  }

  return [{ id: `${normalizedDayLabel}-slot-1`, start: "09:00", end: "20:00" }];
}

function getSellingTimeDetailSchedule(record) {
  const scheduleMap = new Map(
    Array.isArray(record?.schedule)
      ? record.schedule.map((day) => [day?.label, day])
      : []
  );
  const enabledDaySet = new Set(getSellingTimeDaysFromRecord(record));

  return SELLING_TIME_DAY_OPTIONS.map((day) => {
    const matchedDay = scheduleMap.get(day.label);
    const defaultEnabled = enabledDaySet.has(day.label);
    const enabled = Boolean(matchedDay?.enabled ?? defaultEnabled);
    const is24Hours = Boolean(
      matchedDay?.is24Hours ??
      (enabled && String(record?.name).trim() === "All Day")
    );
    const slotsSource =
      Array.isArray(matchedDay?.slots) && matchedDay.slots.length
        ? matchedDay.slots
        : enabled
          ? getDefaultSellingTimeSlotsForRecord(record?.name, day.label)
          : [];

    return {
      id: day.id,
      label: day.label,
      enabled,
      is24Hours,
      manualSlots:
        enabled && !is24Hours
          ? slotsSource.map((slot, index) => ({
            id: slot?.id ?? `${day.id}-slot-${index + 1}`,
            start: slot?.start ?? "",
            end: slot?.end ?? "",
          }))
          : [createSellingTimeSlot("", "")],
      slots: enabled
        ? slotsSource.map((slot, index) => ({
          id: slot?.id ?? `${day.id}-slot-${index + 1}`,
          start: slot?.start ?? "",
          end: slot?.end ?? "",
        }))
        : [],
    };
  });
}

function createSellingTimeDetailDraftFromRecord(record) {
  return {
    id: record?.id ?? "",
    name: record?.name ?? "",
    days: getSellingTimeDetailSchedule(record).map((day) =>
      createSellingTimeDaySchedule(day)
    ),
  };
}

function cloneSellingTimeDetailDraftState(value) {
  return JSON.parse(JSON.stringify(value));
}

function getSellingTimeDetailValidationMessage(detailDraft, detailEditing) {
  if (!detailDraft || !detailEditing) return null;

  if (detailEditing.kind === "field" && detailEditing.field === "name") {
    if (!detailDraft.name.trim()) {
      return "Field cannot be empty";
    }
  }

  if (detailEditing.kind === "schedule-day") {
    const day = (detailDraft.days ?? []).find(
      (entry) => entry.id === detailEditing.dayId
    );
    if (!day || !day.enabled || day.is24Hours) return null;

    const hasInvalidSlot = (day.slots ?? []).some(
      (slot) => !slot?.start || !slot?.end
    );

    if (hasInvalidSlot) {
      return "Field cannot be empty";
    }
  }

  return null;
}

function getSellingTimeDetailValidationErrors(detailDraft, detailEditing) {
  if (!detailDraft || !detailEditing) return {};

  if (detailEditing.kind !== "schedule-day") {
    return {};
  }

  const day = (detailDraft.days ?? []).find(
    (entry) => entry.id === detailEditing.dayId
  );
  if (!day || !day.enabled || day.is24Hours) {
    return {};
  }

  return (day.slots ?? []).reduce((errors, slot) => {
    if (!slot?.start) {
      errors[getSellingTimeSlotErrorKey(day.id, slot.id, "start")] = true;
    }
    if (!slot?.end) {
      errors[getSellingTimeSlotErrorKey(day.id, slot.id, "end")] = true;
    }
    return errors;
  }, {});
}

function isSameSellingTimeDetailEditing(currentEditing, nextEditing) {
  if (
    !currentEditing ||
    !nextEditing ||
    currentEditing.kind !== nextEditing.kind
  ) {
    return false;
  }

  if (currentEditing.kind === "field" && nextEditing.kind === "field") {
    return currentEditing.field === nextEditing.field;
  }

  if (
    currentEditing.kind === "schedule-day" &&
    nextEditing.kind === "schedule-day"
  ) {
    return currentEditing.dayId === nextEditing.dayId;
  }

  return false;
}

const CATEGORY_HIERARCHY_SEPARATOR = " > ";
const MAX_CATEGORY_NESTING_LEVEL = 3;
const DUPLICATE_CATALOG_SNACKBAR_MESSAGE =
  "Catalog name, unit, and category combination already exists";
const DUPLICATE_CATEGORY_ERROR_MESSAGE = "Category name already exists";
const DUPLICATE_UNIT_ERROR_MESSAGE = "Unit name already exists";
const DUPLICATE_MODIFIER_ERROR_MESSAGE = "Modifier name already exists";
const DUPLICATE_PRICING_RULE_ERROR_MESSAGE =
  "Special pricing rule name already exists";
const DUPLICATE_DEVICE_ERROR_MESSAGE = "Device name already exists";
const DUPLICATE_KDS_GROUP_ERROR_MESSAGE = "KDS group name already exists";
const DUPLICATE_ROLE_ACCESS_ERROR_MESSAGE = "Role access name already exists";

function normalizeDuplicateNameValue(value = "") {
  return String(value ?? "").trim().toLowerCase();
}

function hasDuplicateRecordName(
  rows = [],
  value = "",
  {
    excludeId = null,
    getRowId = (row) => row?.id,
    getRowValue = (row) => row?.name,
  } = {}
) {
  const normalizedValue = normalizeDuplicateNameValue(value);
  if (!normalizedValue) return false;

  return rows.some((row) => {
    if (excludeId !== null && getRowId(row) === excludeId) {
      return false;
    }

    return normalizeDuplicateNameValue(getRowValue(row)) === normalizedValue;
  });
}

function getCategoryHierarchyDepth(path = "") {
  if (!path) return 0;
  return path.split(CATEGORY_HIERARCHY_SEPARATOR).length;
}

function getCategorySubtreeDepth(categoryRows = [], rootPath = "") {
  if (!rootPath) return 1;

  const rootDepth = getCategoryHierarchyDepth(rootPath);
  const matchingDepths = categoryRows
    .map((row) => row.hierarchyPath || row.name)
    .filter(
      (path) =>
        path === rootPath ||
        path.startsWith(`${rootPath}${CATEGORY_HIERARCHY_SEPARATOR}`)
    )
    .map((path) => getCategoryHierarchyDepth(path) - rootDepth + 1);

  return matchingDepths.length ? Math.max(...matchingDepths) : 1;
}

function buildOrderedCategoryRows(categoryRows = []) {
  const rowsByParent = new Map();

  categoryRows.forEach((row) => {
    const parentKey = row.parentCategory || "";
    if (!rowsByParent.has(parentKey)) {
      rowsByParent.set(parentKey, []);
    }
    rowsByParent.get(parentKey).push(row);
  });

  const visitedIds = new Set();

  function visit(parentKey = "", trail = new Set()) {
    const children = rowsByParent.get(parentKey) ?? [];

    return children.flatMap((row) => {
      if (visitedIds.has(row.id) || trail.has(row.name)) {
        return [];
      }

      visitedIds.add(row.id);
      const nextTrail = new Set(trail);
      nextTrail.add(row.name);

      return [row, ...visit(row.name, nextTrail)];
    });
  }

  const orderedRows = visit("");
  return orderedRows.concat(
    categoryRows.filter((row) => !visitedIds.has(row.id))
  );
}

function createCategoryTreeOption(row) {
  return {
    value: row.name,
    label: row.name,
    indentLevel: Math.max(
      0,
      getCategoryHierarchyDepth(row.hierarchyPath || row.name) - 1
    ),
  };
}

function buildCategoryParentOptions(
  categoryRows = [],
  {
    excludeId = null,
    blockedPaths = [],
    maxDepth = MAX_CATEGORY_NESTING_LEVEL,
    maxSubtreeDepth = 1,
  } = {}
) {
  const orderedRows = buildOrderedCategoryRows(categoryRows);

  return [
    {
      value: "None (Main Category)",
      label: "None (Main Category)",
    },
    ...orderedRows
      .filter((row) => {
        if (row.id === excludeId) return false;

        const path = row.hierarchyPath || row.name;
        const itemDepth = getCategoryHierarchyDepth(path);
        const isBlocked = blockedPaths.some(
          (blockedPath) =>
            path === blockedPath ||
            path.startsWith(`${blockedPath}${CATEGORY_HIERARCHY_SEPARATOR}`)
        );

        return !isBlocked && itemDepth + maxSubtreeDepth <= maxDepth;
      })
      .map(createCategoryTreeOption),
  ];
}

function normalizeCatalogIdentityValue(value, fallback = "") {
  return String(value ?? fallback).trim().toLowerCase();
}

function isDuplicateCatalogRecord(candidate, catalogRows = []) {
  const normalizedName = normalizeCatalogIdentityValue(candidate?.name);
  const normalizedUnit = normalizeCatalogIdentityValue(
    candidate?.unit,
    "Pcs"
  );
  const normalizedCategory = normalizeCatalogIdentityValue(
    candidate?.category,
    "Uncategorized"
  );

  if (!normalizedName || !normalizedUnit || !normalizedCategory) {
    return false;
  }

  return catalogRows.some(
    (row) =>
      row.id !== candidate?.id &&
      normalizeCatalogIdentityValue(row.name) === normalizedName &&
      normalizeCatalogIdentityValue(row.unit, "Pcs") === normalizedUnit &&
      normalizeCatalogIdentityValue(row.category, "Uncategorized") ===
      normalizedCategory
  );
}

function buildCatalogCategoryOptions(categoryRows = [], catalogRows = []) {
  const orderedRows = buildOrderedCategoryRows(categoryRows);
  const nextOptions = [{ value: "Uncategorized", label: "Uncategorized" }];
  const seenValues = new Set(["uncategorized"]);

  orderedRows.forEach((row) => {
    nextOptions.push(createCategoryTreeOption(row));
    seenValues.add(normalizeDuplicateNameValue(row.name));
  });

  catalogRows.forEach((row) => {
    const categoryName = row.category || "Uncategorized";
    const normalizedCategoryName = normalizeDuplicateNameValue(categoryName);

    if (!categoryName || seenValues.has(normalizedCategoryName)) {
      return;
    }

    seenValues.add(normalizedCategoryName);
    nextOptions.push({
      value: categoryName,
      label: categoryName,
    });
  });

  return nextOptions;
}

function buildModifierCatalogGroups(categoryRows = [], catalogRows = []) {
  const orderedCategoryRows = buildOrderedCategoryRows(categoryRows);
  const catalogsByCategory = new Map();

  catalogRows.forEach((row) => {
    const categoryName = row.category || "Uncategorized";
    if (!catalogsByCategory.has(categoryName)) {
      catalogsByCategory.set(categoryName, []);
    }
    catalogsByCategory.get(categoryName).push(row);
  });

  const groups = [];
  const usedCategories = new Set();

  if (catalogsByCategory.has("Uncategorized")) {
    groups.push({
      id: "Uncategorized",
      label: "Uncategorized",
      indentLevel: 0,
      items: catalogsByCategory.get("Uncategorized").map((row) => ({
        id: row.id,
        label: row.name,
        value: row.name,
        indentLevel: 1,
      })),
    });
    usedCategories.add("uncategorized");
  }

  orderedCategoryRows.forEach((row) => {
    const groupItems = catalogsByCategory.get(row.name) ?? [];
    if (!groupItems.length) {
      return;
    }

    const groupIndentLevel = Math.max(
      0,
      getCategoryHierarchyDepth(row.hierarchyPath || row.name) - 1
    );

    groups.push({
      id: row.id,
      label: row.name,
      indentLevel: groupIndentLevel,
      items: groupItems.map((item) => ({
        id: item.id,
        label: item.name,
        value: item.name,
        indentLevel: groupIndentLevel + 1,
      })),
    });
    usedCategories.add(normalizeDuplicateNameValue(row.name));
  });

  catalogsByCategory.forEach((groupItems, categoryName) => {
    const normalizedCategoryName = normalizeDuplicateNameValue(categoryName);
    if (usedCategories.has(normalizedCategoryName)) {
      return;
    }

    groups.push({
      id: categoryName,
      label: categoryName,
      indentLevel: 0,
      items: groupItems.map((item) => ({
        id: item.id,
        label: item.name,
        value: item.name,
        indentLevel: 1,
      })),
    });
  });

  return groups;
}

function getCategoryHierarchyPath(
  categoryName,
  categoryMap,
  trail = new Set()
) {
  if (!categoryName) return "";
  if (trail.has(categoryName)) return categoryName;

  const category = categoryMap.get(categoryName);
  if (!category) return categoryName;

  const parentCategory = category.parentCategory || "";
  if (!parentCategory) return category.name;

  const nextTrail = new Set(trail);
  nextTrail.add(categoryName);
  const parentPath = getCategoryHierarchyPath(
    parentCategory,
    categoryMap,
    nextTrail
  );

  return parentPath
    ? `${parentPath}${CATEGORY_HIERARCHY_SEPARATOR}${category.name}`
    : category.name;
}

function buildCategoryRows(categories = [], catalogRows = []) {
  const categoryMap = new Map(
    categories.map((row) => [
      row.name,
      {
        ...row,
        parentCategory: row.parentCategory || "",
      },
    ])
  );

  return categories.map((row) => {
    const hierarchyPath = getCategoryHierarchyPath(row.name, categoryMap);
    const connectedCatalogNames = catalogRows
      .filter((catalog) => (catalog.category || "Uncategorized") === row.name)
      .map((catalog) => catalog.name);

    return {
      ...row,
      parentCategory: row.parentCategory || "",
      hierarchyPath,
      hierarchyDisplay: row.parentCategory ? hierarchyPath : "Main Category",
      connectedCatalogDisplay: connectedCatalogNames.length
        ? connectedCatalogNames.join(", ")
        : "-",
      connectedCatalogSearch: connectedCatalogNames.join(" "),
    };
  });
}

function buildModifierRows(modifiers = [], modifierDetailDraft = null) {
  return modifiers.map((row) => {
    const optionNames = Array.isArray(row.options)
      ? row.options
        .map((option) => option?.name?.trim?.() ?? "")
        .filter(Boolean)
      : [];
    const connectedCatalogNames = Array.isArray(row.connectedCatalogItems)
      ? row.connectedCatalogItems.filter(Boolean)
      : [];
    const availabilityValue =
      modifierDetailDraft?.id === row.id
        ? modifierDetailDraft.availability
        : row.availability;

    return {
      ...row,
      modifierOptionsDisplay: optionNames.length
        ? optionNames.join(", ")
        : row.modifierOptions || "-",
      modifierOptionsSearch: optionNames.join(" "),
      connectedCatalogDisplay: connectedCatalogNames.length
        ? connectedCatalogNames.join(", ")
        : row.connectedCatalog || "-",
      connectedCatalogSearch: connectedCatalogNames.join(" "),
      availability: (
        <div
          className="modifier-table-availability-cell"
          onClick={(event) => {
            event.stopPropagation();
            handleModifierListAvailabilityToggle(row.id);
          }}
          onMouseDown={(event) => event.stopPropagation()}
          onPointerDown={(event) => event.stopPropagation()}
        >
          <Toggle
            checked={availabilityValue !== false}
            ariaLabel={`Modifier availability for ${row.name}`}
          />
        </div>
      ),
    };
  });
}

function buildUnitRows(units = [], catalogRows = []) {
  return units.map((row) => {
    const connectedCatalogNames = catalogRows
      .filter((catalog) => (catalog.unit || "Pcs") === row.name)
      .map((catalog) => catalog.name);
    const connectedCatalogCount = connectedCatalogNames.length;

    return {
      ...row,
      precisionDisplay: normalizeUnitPrecisionOption(row.precision),
      connectedCatalogDisplay: connectedCatalogNames.length
        ? connectedCatalogNames.join(", ")
        : "-",
      connectedCatalogSearch: connectedCatalogNames.join(" "),
    };
  });
}

function buildAssignedUnitRows(units = []) {
  const rows = [];
  let currentGroup = "";

  units.forEach((unit) => {
    if (unit.group && unit.group !== currentGroup) {
      rows.push({
        type: "group",
        id: `unit-group-${unit.group}`,
        label: unit.group,
      });
      currentGroup = unit.group;
    }

    rows.push({ type: "unit", ...unit });
  });

  return rows;
}

function buildCatalogAssignedUnitRows(units = []) {
  return normalizeCatalogAssignedUnits(units).map((unit) => ({
    type: "unit",
    ...unit,
    subtitle:
      unit.subtitle ?? (unit.group && unit.group !== unit.name ? unit.group : ""),
  }));
}

function getModifierUnitAssignmentColumns(options = []) {
  const namedOptions = options
    .map((option, index) => ({
      id: option?.id ?? `modifier-assignment-column-${index}`,
      name: option?.name?.trim?.() ?? "",
      additionalPrice: getNormalizedNominalDigits(option?.additionalPrice),
    }))
    .filter((option) => option.name);

  return namedOptions.length
    ? namedOptions
    : [
      {
        id: "modifier-assignment-empty",
        name: "-",
        additionalPrice: "",
        isPlaceholder: true,
      },
    ];
}

function getModifierUnitAssignmentValue(option, unit) {
  return "-";
}

function formatModifierDetailOptionPrice(value) {
  const rawValue = String(value ?? "").trim();
  if (!rawValue || rawValue === "0") return "Free";

  const digits = rawValue.replace(/[^\d]/g, "");
  return digits ? `+ ${formatIdr(Number(digits))}` : rawValue;
}

function getModifierCatalogSelectSummary(
  selectedCatalogs = [],
  groups = [],
  placeholder = "Select Catalog"
) {
  const normalizedValues = Array.isArray(selectedCatalogs)
    ? selectedCatalogs.filter(Boolean)
    : [];
  const totalCatalogs = groups.flatMap((group) => group.items ?? []).length;

  if (totalCatalogs && normalizedValues.length === totalCatalogs) {
    return "All Catalogs Selected";
  }

  if (normalizedValues.length === 1) {
    const selectedItem = groups
      .flatMap((group) => group.items ?? [])
      .find(
        (item) =>
          item.value === normalizedValues[0] || item.id === normalizedValues[0]
      );
    return selectedItem?.label ?? normalizedValues[0];
  }

  if (normalizedValues.length > 1) {
    return `${normalizedValues.length} Catalogs Selected`;
  }

  return placeholder;
}

function getModifierConnectedCatalogSummary(
  selectedCatalogs = []
) {
  const normalizedValues = Array.isArray(selectedCatalogs)
    ? selectedCatalogs.filter(Boolean)
    : [];

  return normalizedValues.length ? normalizedValues.join(", ") : "-";
}

function getModifierDetailUnitAssignmentValue(option, unit) {
  if (!option || option.isPlaceholder) return "-";
  if (!unit || unit.maxOverridePrice === "Not Allowed") return "-";

  const rawValue =
    unit.optionValues?.[option.id] ??
    unit.optionValues?.[option.name] ??
    option.additionalPrice ??
    "";
  const normalizedValue = String(rawValue ?? "").trim();

  if (!normalizedValue || normalizedValue === "0") return "Free";
  if (normalizedValue === "-") return "-";

  const digits = normalizedValue.replace(/[^\d]/g, "");
  return digits ? formatNominalInput(digits) : normalizedValue;
}

function buildSellingTimeRows(sellingTimes = []) {
  return sellingTimes.map((row) => {
    const dayLabels = getSellingTimeDaysFromRecord(row);

    return {
      ...row,
      dayDisplay: dayLabels.length ? dayLabels.join(", ") : "-",
      daySearch: dayLabels.join(" "),
    };
  });
}

function cloneCatalogPhotos(photos = []) {
  return photos.map((photo) => ({ ...photo }));
}

function clonePackageItems(items = []) {
  return (items ?? []).map((item) => ({ ...item }));
}

function cloneCatalogIngredients(items = []) {
  return (items ?? []).map((item) => ({ ...item }));
}

function cloneAssignedUnits(units = []) {
  return units.map((unit) => ({ ...unit }));
}

function createCatalogPhotoSet(prefix, count = 3) {
  const imagePool = [
    ASSETS.detailPhotoA,
    ASSETS.detailPhotoB,
    ASSETS.detailPhotoC,
    ASSETS.detailPhotoA,
    ASSETS.detailPhotoB,
  ];

  return Array.from({ length: count }, (_, index) => imagePool[index % imagePool.length]).map((url, index) => ({
    id: `${prefix}-photo-${index + 1}`,
    name: `Catalog photo ${index + 1}`,
    url,
    isMain: index === 0,
    objectUrl: false,
  }));
}

function getCatalogPhotoPoolForRecord(record = {}) {
  const normalizedName = String(record?.name ?? "").trim().toLowerCase();
  const normalizedCategory = String(record?.category ?? "").trim().toLowerCase();
  const normalizedType = String(record?.type ?? "").trim().toLowerCase();

  if (
    normalizedType === "package" ||
    normalizedName.includes("package") ||
    normalizedName.includes("combo")
  ) {
    return [
      ASSETS.catalogPhotoCombo,
      ASSETS.catalogPhotoBurger,
      ASSETS.catalogPhotoCoffee,
      ASSETS.catalogPhotoFries,
      ASSETS.catalogPhotoDessert,
    ];
  }

  if (normalizedName.includes("burger")) {
    return [
      ASSETS.catalogPhotoBurger,
      ASSETS.catalogPhotoFries,
      ASSETS.catalogPhotoCombo,
    ];
  }

  if (
    normalizedName.includes("linguine") ||
    normalizedName.includes("pasta") ||
    normalizedName.includes("pesto")
  ) {
    return [
      ASSETS.catalogPhotoPasta,
      ASSETS.catalogPhotoSalad,
      ASSETS.catalogPhotoDessert,
    ];
  }

  if (normalizedName.includes("cake")) {
    return [
      ASSETS.catalogPhotoDessert,
      ASSETS.catalogPhotoCoffee,
      ASSETS.catalogPhotoCombo,
    ];
  }

  if (normalizedName.includes("salad")) {
    return [
      ASSETS.catalogPhotoSalad,
      ASSETS.catalogPhotoPasta,
      ASSETS.catalogPhotoDessert,
    ];
  }

  if (normalizedName.includes("fries")) {
    return [
      ASSETS.catalogPhotoFries,
      ASSETS.catalogPhotoBurger,
      ASSETS.catalogPhotoCombo,
    ];
  }

  if (
    normalizedName.includes("coffee") ||
    normalizedCategory.includes("beverage")
  ) {
    return [
      ASSETS.catalogPhotoCoffee,
      ASSETS.catalogPhotoDessert,
      ASSETS.catalogPhotoCombo,
    ];
  }

  if (normalizedCategory.includes("dessert")) {
    return [
      ASSETS.catalogPhotoDessert,
      ASSETS.catalogPhotoCoffee,
      ASSETS.catalogPhotoSalad,
    ];
  }

  if (normalizedCategory.includes("appetizer")) {
    return [
      ASSETS.catalogPhotoSalad,
      ASSETS.catalogPhotoFries,
      ASSETS.catalogPhotoBurger,
    ];
  }

  return [
    ASSETS.detailPhotoA,
    ASSETS.detailPhotoB,
    ASSETS.detailPhotoC,
  ];
}

function createCatalogPhotoSetForRecord(record, count = 3) {
  const imagePool = getCatalogPhotoPoolForRecord(record);

  return Array.from(
    { length: count },
    (_, index) => imagePool[index % imagePool.length]
  ).map((url, index) => ({
    id: `${record?.id ?? "catalog"}-photo-${index + 1}`,
    name: `Catalog photo ${index + 1}`,
    url,
    isMain: index === 0,
    objectUrl: false,
  }));
}

function createCatalogAssignedUnits(selectedIds, overrides = {}) {
  return normalizeCatalogAssignedUnits(createAssignedUnitsFromIds(selectedIds).map((unit) => ({
    ...unit,
    ...(overrides[unit.id] ?? {}),
  })));
}

function createCatalogSeedRecord(record) {
  const type = record?.type ?? "single";

  return {
    type,
    modifier: [],
    unit: "Pcs",
    price: String(record.basePrice ?? 0),
    allowOverridePrice: false,
    packageItems: [],
    ...record,
    category: getCatalogCategoryForType(type, record?.category),
    photos: cloneCatalogPhotos(
      record?.photos ?? createCatalogPhotoSetForRecord(record, 3)
    ),
    assignedUnits: normalizeCatalogAssignedUnits(record?.assignedUnits ?? []),
  };
}

function createCatalogDetailDraftFromRecord(record) {
  const type = record?.type ?? "single";

  return {
    id: record?.id ?? "",
    availability: record?.availability ?? true,
    photos: cloneCatalogPhotos(record?.photos ?? []),
    type,
    name: record?.name ?? "",
    description: record?.description ?? "",
    unit: record?.unit ?? "Pcs",
    category: getCatalogCategoryForType(type, record?.category),
    modifier: Array.isArray(record?.modifier) ? [...record.modifier] : [],
    sellingTime: record?.sellingTime ?? "",
    price: String(record?.price ?? record?.basePrice ?? 0),
    overridePrice: String(record?.overridePrice ?? record?.price ?? record?.basePrice ?? 0),
    allowOverridePrice: Boolean(record?.allowOverridePrice),
    packageItems:
      type === "package"
        ? normalizePackageItems(clonePackageItems(record?.packageItems ?? []))
        : clonePackageItems(record?.packageItems ?? []),
    assignedUnits: normalizeCatalogAssignedUnits(
      cloneAssignedUnits(record?.assignedUnits ?? [])
    ),
    trackStock: Boolean(record?.trackStock),
    ingredients: normalizeCatalogIngredients(
      cloneCatalogIngredients(record?.ingredients ?? [])
    ),
    preparationTime: String(record?.preparationTime ?? ""),
    routing: record?.routing ?? "KDS Kitchen",
  };
}


function cloneCatalogDetailDraftState(value) {
  return JSON.parse(JSON.stringify(value));
}

function getCatalogDetailValidationMessage(detailDraft, detailEditing) {
  if (!detailDraft || !detailEditing) return null;

  if (detailEditing.kind === "all") {
    if (!detailDraft.name.trim()) {
      return "Field cannot be empty";
    }
    if (!detailDraft.category) {
      return "Field cannot be empty";
    }

    if (detailDraft.trackStock && (detailDraft.ingredients ?? []).length === 0) {
      return "At least one ingredient is required when stock tracking is enabled";
    }

    if (
      detailDraft.type === "package" &&
      (detailDraft.packageItems ?? []).some((item) =>
        Boolean(item.catalogId) !== Boolean(item.qty)
      )
    ) {
      return "Field cannot be empty";
    }
  }

  if (detailEditing.kind === "field") {
    if (detailEditing.field === "name" && !detailDraft.name.trim()) {
      return "Field cannot be empty";
    }
    if (detailEditing.field === "category" && !detailDraft.category) {
      return "Field cannot be empty";
    }
  }

  if (detailEditing.kind === "package-row") {
    const currentRow = detailDraft.packageItems.find(
      (item) => item.id === detailEditing.rowId
    );
    if (!currentRow?.catalogId || !currentRow.qty) {
      return "Field cannot be empty";
    }
  }

  if (detailEditing.kind === "assignment-row") {
    const currentUnit = detailDraft.assignedUnits.find(
      (item) => item.id === detailEditing.unitId
    );
    if (!currentUnit?.maxOverridePrice) {
      return "Field cannot be empty";
    }
  }

  return null;
}

function isSameCatalogDetailEditing(currentEditing, nextEditing) {
  if (
    !currentEditing ||
    !nextEditing ||
    currentEditing.kind !== nextEditing.kind
  ) {
    return false;
  }

  if (currentEditing.kind === "all" && nextEditing.kind === "all") {
    return true;
  }

  if (currentEditing.kind === "field" && nextEditing.kind === "field") {
    return currentEditing.field === nextEditing.field;
  }

  if (
    currentEditing.kind === "package-row" &&
    nextEditing.kind === "package-row"
  ) {
    return currentEditing.rowId === nextEditing.rowId;
  }

  if (
    currentEditing.kind === "assignment-row" &&
    nextEditing.kind === "assignment-row"
  ) {
    return currentEditing.unitId === nextEditing.unitId;
  }

  return false;
}

function getNextCatalogDetailTypeDraft(detailDraft, nextType) {
  return {
    ...detailDraft,
    type: nextType,
    modifier: nextType === "single" ? detailDraft.modifier : [],
    packageItems:
      nextType === "package"
        ? detailDraft.packageItems.length
          ? normalizePackageItems(detailDraft.packageItems)
          : [createEmptyPackageItem()]
        : [],
  };
}

function getCatalogDetailAssignmentEditingDraft(detailDraft, unitId) {
  return {
    ...detailDraft,
    assignedUnits: (detailDraft.assignedUnits ?? []).map((unit) =>
      unit.id === unitId
        ? {
          ...unit,
          overridePriceInput:
            unit.overridePrice === "-"
              ? ""
              : String(unit.overridePrice).replace(/[^\d]/g, ""),
        }
        : unit
    ),
  };
}

function disposeCatalogPhotos(photos) {
  photos.forEach((photo) => {
    if (photo.objectUrl) {
      window.URL.revokeObjectURL(photo.url);
    }
  });
}

