function ModifierOptionsTable({
  options,
  isEditing,
  dragOverOptionId,
  optionNameErrors = [],
  optionIngredientQtyErrors = [],
  ingredientOptions = [],
  onOptionChange,
  onRemoveOption,
  onAddOption,
  onDragStart,
  onDragEnd,
  onDragOver,
  onDrop,
  addButtonDisabled = false,
  addButtonDataAttribute,
  rowDataAttribute,
  emptyReadonlyContent = null,
}) {
  if (!isEditing && !options.length) {
    return emptyReadonlyContent;
  }

  return (
    <div className="modifier-option-table-shell">
      <div className="modifier-option-table__scroll">
        <section
          className={`modifier-option-table ${isEditing
            ? "modifier-option-table--editable"
            : "modifier-option-table--readonly modifier-option-table--with-availability"
            }`}
        >
          <div className="modifier-option-table__row modifier-option-table__row--header">
            <div className="modifier-option-table__header-cell modifier-option-table__header-cell--handle" />
            <div className="modifier-option-table__header-cell modifier-option-table__header-cell--name">
              <p className="type-title-3">Option Name</p>
            </div>
            <div className="modifier-option-table__header-cell modifier-option-table__header-cell--price">
              <p className="type-title-3">Additional Price</p>
            </div>
            <div className="modifier-option-table__header-cell modifier-option-table__header-cell--ingredient">
              <p className="type-title-3">Ingredient</p>
            </div>
            <div className="modifier-option-table__header-cell modifier-option-table__header-cell--qty">
              <p className="type-title-3">Qty</p>
            </div>
            {isEditing ? (
              <div className="modifier-option-table__header-cell modifier-option-table__header-cell--action" />
            ) : (
              <div className="modifier-option-table__header-cell modifier-option-table__header-cell--availability">
                <p className="type-title-3">Availability</p>
              </div>
            )}
          </div>
          {options.map((option, index) => {
            const optionNameError = optionNameErrors.includes(option.id);
            const optionIngredientQtyError =
              optionIngredientQtyErrors.includes(option.id);
            const hasIngredient = hasModifierOptionIngredient(option);
            const ingredientUnit = getModifierIngredientSelection(option)
              .ingredientUnit;

            return (
              <div
                key={option.id}
                {...(rowDataAttribute
                  ? { [rowDataAttribute]: "true" }
                  : {})}
                className={`modifier-option-table__row${dragOverOptionId === option.id ? " is-drag-over" : ""
                  }`}
                onDragOver={
                  isEditing
                    ? (event) => {
                      event.preventDefault();
                      event.dataTransfer.dropEffect = "move";
                      onDragOver?.(option.id);
                    }
                    : undefined
                }
                onDrop={
                  isEditing
                    ? (event) => {
                      event.preventDefault();
                      onDrop?.(option.id);
                    }
                    : undefined
                }
              >
                <div className="modifier-option-table__cell modifier-option-table__cell--handle">
                  <ModifierReorderHandle
                    ariaLabel={`Reorder option ${index + 1}`}
                    disabled={!isEditing}
                    onDragStart={
                      isEditing
                        ? (event) => onDragStart?.(option.id, event)
                        : undefined
                    }
                    onDragEnd={isEditing ? onDragEnd : undefined}
                  />
                </div>
                <div className="modifier-option-table__cell modifier-option-table__cell--name">
                  {isEditing ? (
                    <div className="modifier-option-table__field-stack">
                      <label
                        className={`modifier-option-table__field-shell${optionNameError ? " is-error" : ""
                          }`}
                      >
                        <input
                          className={`type-subtitle-2${option.name ? "" : " text-tertiary"}`}
                          type="text"
                          value={option.name}
                          placeholder={`Option Name ${index + 1}`}
                          onChange={(event) =>
                            onOptionChange?.(
                              option.id,
                              "name",
                              event.target.value
                            )
                          }
                        />
                      </label>
                      {optionNameError ? (
                        <p className="modifier-option-table__field-error type-body">
                          Field cannot be empty
                        </p>
                      ) : null}
                    </div>
                  ) : (
                    <p className="type-subtitle-2">{option.name || "-"}</p>
                  )}
                </div>
                <div className="modifier-option-table__cell modifier-option-table__cell--price">
                  {isEditing ? (
                    <ModifierOptionPriceField
                      value={option.additionalPrice}
                      onChange={(value) =>
                        onOptionChange?.(option.id, "additionalPrice", value)
                      }
                    />
                  ) : (
                    <p className="type-subtitle-2">
                      {formatModifierDetailOptionPrice(option.additionalPrice)}
                    </p>
                  )}
                </div>
                <div className="modifier-option-table__cell modifier-option-table__cell--ingredient">
                  {isEditing ? (
                    <div className="modifier-option-table__field-stack">
                      <label className="modifier-option-table__field-shell modifier-option-table__field-shell--select">
                        <PackageItemSelectField
                          value={option.selectedIngredient}
                          options={ingredientOptions}
                          placeholder="Select Ingredient"
                          allowClear
                          clearLabel="No Ingredient"
                          emptyCopy="No ingredient available"
                          onChange={(value) =>
                            onOptionChange?.(
                              option.id,
                              "selectedIngredient",
                              value
                            )
                          }
                        />
                      </label>
                    </div>
                  ) : (
                    <p className="type-subtitle-2">
                      {option.selectedIngredient || "-"}
                    </p>
                  )}
                </div>
                <div className="modifier-option-table__cell modifier-option-table__cell--qty">
                  {isEditing ? (
                    <ModifierOptionQtyField
                      value={option.ingredientQty}
                      unitLabel={ingredientUnit}
                      disabled={!hasIngredient}
                      error={optionIngredientQtyError}
                      onChange={(value) =>
                        onOptionChange?.(option.id, "ingredientQty", value)
                      }
                    />
                  ) : (
                    <p className="type-subtitle-2">
                      {hasIngredient && option.ingredientQty
                        ? `${option.ingredientQty} ${ingredientUnit}`.trim()
                        : "-"}
                    </p>
                  )}
                </div>
                {isEditing ? (
                  <div className="modifier-option-table__cell modifier-option-table__cell--action">
                    <TableActionButton
                      tooltip="Remove"
                      onClick={() => onRemoveOption?.(option.id)}
                      ariaLabel={`Remove option ${index + 1}`}
                    >
                      <Icon
                        name="delete"
                        className="lab-icon lab-icon--16"
                        alt="Delete"
                      />
                    </TableActionButton>
                  </div>
                ) : (
                  <div className="modifier-option-table__cell modifier-option-table__cell--availability">
                    <Toggle
                      checked={option.isAvailable !== false}
                      onChange={() =>
                        onOptionChange?.(
                          option.id,
                          "isAvailable",
                          option.isAvailable === false ? true : false
                        )
                      }
                      ariaLabel={`Availability for ${option.name || "Option"}`}
                    />
                  </div>
                )}
              </div>
            );
          })}
        </section>
      </div>
      {isEditing ? (
        <button
          type="button"
          className="modifier-option-table__add"
          disabled={addButtonDisabled}
          {...(addButtonDataAttribute
            ? { [addButtonDataAttribute]: "true" }
            : {})}
          onClick={onAddOption}
        >
          <Icon name="modifierOptionAdd" className="lab-icon" alt="" />
          <span className="modifier-option-table__add-label type-title-3">
            Add Option
          </span>
        </button>
      ) : null}
    </div>
  );
}

function CatalogTypeField({ value, onChange }) {
  return (
    <DetailSelectField
      label="Catalog Type"
      required
      value={value}
      options={[
        { value: "single", label: "Single Product" },
        { value: "package", label: "Package" },
      ]}
      onChange={onChange}
      placeholder="Select Catalog Type"
    />
  );
}

function getNormalizedNominalDigits(value) {
  return String(value ?? "")
    .replace(/[^\d]/g, "")
    .replace(/^0+/, "");
}

function formatNominalInput(value) {
  const digits = getNormalizedNominalDigits(value);
  return digits ? new Intl.NumberFormat("id-ID").format(Number(digits)) : "";
}

function PriceField({ value, onChange, error = false }) {
  const displayValue = formatNominalInput(value);

  return (
    <label className="catalog-detail-field">
      <span className="catalog-detail-field__label type-body">
        <span className="catalog-detail-field__required">*</span>
        Price
      </span>
      <span
        className={`catalog-detail-field__shell catalog-detail-field__shell--price${error ? " is-error" : ""
          }`}
      >
        <span className="catalog-detail-field__prefix type-subtitle-1">
          IDR
        </span>
        <ChevronIcon name="selectChevron" size={16} direction="down" />
        <input
          className={`type-subtitle-1${displayValue ? "" : " text-tertiary"}`}
          type="text"
          inputMode="numeric"
          value={displayValue}
          placeholder="0"
          onChange={(event) =>
            onChange(getNormalizedNominalDigits(event.target.value))
          }
        />
      </span>
      {error ? (
        <p className="catalog-detail-field__error type-body">
          Field cannot be empty
        </p>
      ) : null}
    </label>
  );
}

function UnitAssignmentModal({
  open,
  searchValue,
  assignedIds,
  selectedIds,
  descriptionCopy = "Assign this catalog to an entity so it can be used",
  onSearchChange,
  onToggleUnit,
  onToggleGroup,
  onAssignAll,
  onClose,
  onConfirm,
}) {
  if (!open) return null;

  const assignedSet = new Set(assignedIds);
  const normalizedSearch = searchValue.trim().toLowerCase();
  const filteredGroups = BUSINESS_UNIT_ASSIGNMENT_GROUPS.map((group) => {
    const availableUnits = group.units.filter(
      (unit) => !assignedSet.has(unit.id)
    );
    if (!availableUnits.length) return null;

    if (!normalizedSearch) return { ...group, units: availableUnits };

    const matchesGroup = group.label.toLowerCase().includes(normalizedSearch);
    const matchedUnits = matchesGroup
      ? availableUnits
      : availableUnits.filter((unit) =>
        unit.name.toLowerCase().includes(normalizedSearch)
      );

    return matchedUnits.length ? { ...group, units: matchedUnits } : null;
  }).filter(Boolean);
  const hasAvailableUnits = BUSINESS_UNIT_ASSIGNMENT_GROUPS.some((group) =>
    group.units.some((unit) => !assignedSet.has(unit.id))
  );

  return (
    <div className="unit-assignment-modal-overlay" onMouseDown={onClose}>
      <div
        className="unit-assignment-modal"
        role="dialog"
        aria-modal="true"
        aria-labelledby="unit-assignment-modal-title"
        onMouseDown={(event) => event.stopPropagation()}
      >
        <div className="unit-assignment-modal__close-row">
          <button
            type="button"
            className="unit-assignment-modal__close"
            onClick={onClose}
            aria-label="Close entity assignment"
          >
            <Icon name="modalClose" className="lab-icon lab-icon--20" alt="" />
          </button>
        </div>
        <div className="unit-assignment-modal__header">
          <p
            id="unit-assignment-modal-title"
            className="unit-assignment-modal__title type-title-1"
          >
            Entity Assignment
          </p>
          <p className="unit-assignment-modal__copy type-body-bold">
            {descriptionCopy}
          </p>
        </div>
        <div className="unit-assignment-modal__body">
          <label className="unit-assignment-modal__search">
            <Icon
              name="search"
              className="lab-icon lab-icon--20"
              alt="Search"
            />
            <input
              type="search"
              className="type-subtitle-1"
              placeholder="Search Entity"
              value={searchValue}
              onChange={(event) => onSearchChange(event.target.value)}
            />
          </label>
          <div className="unit-assignment-modal__table">
            <div className="unit-assignment-modal__table-head">
              <div className="unit-assignment-modal__header-row">
                <div className="unit-assignment-modal__header-cell">
                  <p className="type-title-3">Entity</p>
                </div>
                <div className="unit-assignment-modal__action-cell">
                  <button
                    type="button"
                    className="unit-assignment-modal__link is-primary type-title-3"
                    onClick={onAssignAll}
                  >
                    Assign to All Entities
                  </button>
                </div>
              </div>
            </div>
            <div className="unit-assignment-modal__table-body">
              {filteredGroups.length ? (
                filteredGroups.map((group) => {
                  const isGroupSelected = group.units.every((unit) =>
                    selectedIds.includes(unit.id)
                  );

                  return (
                    <div key={group.id}>
                      <div className="unit-assignment-modal__group-row">
                        <div className="unit-assignment-modal__group-cell">
                          <p className="type-subtitle-2">{group.label}</p>
                        </div>
                        <div className="unit-assignment-modal__group-cell unit-assignment-modal__action-cell">
                          <button
                            type="button"
                            className={`unit-assignment-modal__link ${isGroupSelected ? "is-danger" : "is-primary"
                              } type-body`}
                            onClick={() => onToggleGroup(group.id)}
                          >
                            {isGroupSelected
                              ? "Clear selected entities in this subsidiary"
                              : "Assign to all entities in this subsidiary"}
                          </button>
                        </div>
                      </div>
                      {group.units.map((unit) => {
                        const isSelected = selectedIds.includes(unit.id);

                        return (
                          <div
                            key={unit.id}
                            className="unit-assignment-modal__unit-row"
                          >
                            <div className="unit-assignment-modal__unit-cell">
                              <p className="type-subtitle-2">{unit.name}</p>
                            </div>
                            <div className="unit-assignment-modal__action-cell">
                              {isSelected ? (
                                <button
                                  type="button"
                                  className="catalog-remove-button type-subtitle-2"
                                  onClick={() => onToggleUnit(unit.id)}
                                >
                                  Remove
                                </button>
                              ) : (
                                <LabButton
                                  label="Assign"
                                  variant="primary"
                                  size="small"
                                  onClick={() => onToggleUnit(unit.id)}
                                />
                              )}
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  );
                })
              ) : (
                <div className="unit-assignment-modal__empty">
                  <p className="type-subtitle-2">
                    {hasAvailableUnits
                      ? "No entity matches your search"
                      : "All entities are already assigned"}
                  </p>
                </div>
              )}
            </div>
          </div>
        </div>
        <div className="unit-assignment-modal__footer">
          <LabButton
            label="Confirm Assignment"
            variant="primary"
            size="large"
            fullWidth
            disabled={!selectedIds.length}
            onClick={onConfirm}
          />
        </div>
      </div>
    </div>
  );
}

