function DeviceStatusConfirmationModal({
  open,
  deviceName,
  nextStatus,
  disconnectLabel = "Disconnect",
  onClose,
  onConfirm,
}) {
  if (!open) return null;

  const isConnect = nextStatus === "Connected";
  const isTurnOffConnection = !isConnect && disconnectLabel === "Turn Off Connection";

  return (
    <div className="modal-overlay discard-changes-modal-overlay" onMouseDown={onClose}>
      <div
        className="discard-changes-modal"
        role="dialog"
        aria-modal="true"
        aria-labelledby="device-status-confirmation-modal-title"
        onMouseDown={(event) => event.stopPropagation()}
      >
        <div className="discard-changes-modal__header">
          <p
            id="device-status-confirmation-modal-title"
            className="type-title-1"
          >
            {isConnect
              ? "Turn on Device Connection?"
              : isTurnOffConnection
                ? "Turn Off Device Connection?"
                : "Disconnect Device?"}
          </p>
          <button
            type="button"
            className="discard-changes-modal__close"
            onClick={onClose}
            aria-label="Close device status confirmation dialog"
          >
            <Icon name="modalClose" className="lab-icon lab-icon--20" alt="" />
          </button>
        </div>
        <div className="discard-changes-modal__copy type-body text-secondary">
          {isConnect
            ? deviceName
              ? `Do you want to turn on the connection for "${deviceName}"?`
              : "This device is now ready to connect and is pending pairing code entry from the device that previously connected on the other side."
            : deviceName
              ? isTurnOffConnection
                ? `Do you want to turn off the connection for "${deviceName}"?`
                : `Are you sure you want to disconnect "${deviceName}"?`
              : isTurnOffConnection
                ? "Are you sure you want to turn off this device connection?"
                : "Are you sure you want to disconnect this device?"}
        </div>
        <div className="discard-changes-modal__actions">
          <LabButton
            label="Cancel"
            variant="secondary"
            size="medium"
            onClick={onClose}
            fullWidth
          />
          <LabButton
            label={
              isConnect
                ? "Yes, Turn On"
                : isTurnOffConnection
                  ? "Yes, Turn Off"
                  : "Yes, Disconnect"
            }
            variant={isConnect ? "primary" : "danger"}
            size="medium"
            onClick={onConfirm}
            fullWidth
          />
        </div>
      </div>
    </div>
  );
}

function formatIdr(amount) {
  return `IDR ${new Intl.NumberFormat("id-ID").format(amount)}`;
}

function createDashboardReportAnchorDate(anchorDate = new Date()) {
  return new Date(
    anchorDate.getFullYear(),
    anchorDate.getMonth(),
    anchorDate.getDate()
  );
}

function formatDashboardReportDate(date) {
  return `${date.getDate()} ${formatShortMonth(date)} ${date.getFullYear()}`;
}

function formatDashboardReportDateValue(date) {
  return [
    date.getFullYear(),
    String(date.getMonth() + 1).padStart(2, "0"),
    String(date.getDate()).padStart(2, "0"),
  ].join("-");
}

function createTodayDashboardReportCustomRange(anchorDate = new Date()) {
  const todayValue = formatDashboardReportDateValue(
    createDashboardReportAnchorDate(anchorDate)
  );

  return {
    start: todayValue,
    end: todayValue,
  };
}

function parseDashboardReportDateValue(value) {
  if (!value) return null;
  const [year, month, day] = value.split("-").map(Number);
  if (!year || !month || !day) return null;
  return new Date(year, month - 1, day);
}

function normalizeDashboardReportDateRange(timeRange, customRange, anchorDate) {
  return normalizeDashboardReportDateRangeWithOffset(
    timeRange,
    customRange,
    anchorDate,
    0
  );
}

function normalizeDashboardReportDateRangeWithOffset(
  timeRange,
  customRange,
  anchorDate,
  offset = 0
) {
  const today = createDashboardReportAnchorDate(anchorDate);

  if (timeRange === "All Time") {
    return { start: null, end: shiftDateByDays(today, -offset) };
  }

  if (timeRange === "Today") {
    const targetDate = shiftDateByDays(today, -offset);
    return { start: targetDate, end: targetDate };
  }

  if (timeRange === "Last 7 Days") {
    const endDate = shiftDateByDays(today, -offset);
    return { start: shiftDateByDays(endDate, -6), end: endDate };
  }

  if (timeRange === "Last 30 Days") {
    const endDate = shiftDateByDays(today, -offset);
    return { start: shiftDateByDays(endDate, -29), end: endDate };
  }

  const start = parseDashboardReportDateValue(customRange.start);
  const end = parseDashboardReportDateValue(customRange.end);

  if (start && end && start.getTime() > end.getTime()) {
    const rangeLength =
      Math.floor((start.getTime() - end.getTime()) / (1000 * 60 * 60 * 24)) + 1;
    return {
      start: shiftDateByDays(end, -offset),
      end: shiftDateByDays(start, -offset),
    };
  }

  if (start && end) {
    return {
      start: shiftDateByDays(start, -offset),
      end: shiftDateByDays(end, -offset),
    };
  }

  return { start, end };
}

function filterDashboardReportRowsByDate(
  rows,
  timeRange,
  customRange,
  anchorDate,
  offset = 0
) {
  const { start, end } = normalizeDashboardReportDateRangeWithOffset(
    timeRange,
    customRange,
    anchorDate,
    offset
  );

  if (!start && !end) return rows;

  return (rows || []).filter((row) => {
    const rowDate = parseDashboardReportDateValue(row.dateValue);
    if (!rowDate) return true;
    if (start && rowDate.getTime() < start.getTime()) return false;
    if (end && rowDate.getTime() > end.getTime()) return false;
    return true;
  });
}

function getDashboardReportDateRangeLengthInDays(
  timeRange,
  customRange,
  anchorDate
) {
  const { start, end } = normalizeDashboardReportDateRange(
    timeRange,
    customRange,
    anchorDate
  );

  if (!start || !end) return Number.POSITIVE_INFINITY;

  return (
    Math.floor((end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24)) + 1
  );
}

function getDashboardTrendCopyForTimeRange(
  timeRange,
  customRange,
  anchorDate = new Date()
) {
  if (timeRange === "Today") return "vs previous day";
  if (timeRange === "Last 7 Days") return "vs previous week";
  if (timeRange === "Last 30 Days") return "vs previous month";
  if (timeRange === "All Time") return "vs previous period";

  if (timeRange === "Custom Date") {
    const rangeLength = getDashboardReportDateRangeLengthInDays(
      timeRange,
      customRange,
      anchorDate
    );

    if (!Number.isFinite(rangeLength)) return "vs previous period";
    if (rangeLength <= 1) return "vs previous day";
    if (rangeLength === 7) return "vs previous week";
    if (rangeLength >= 28 && rangeLength <= 31) return "vs previous month";
  }

  return "vs previous period";
}

function getDashboardReportTrendNavigationLimit(
  timeRange,
  customRange,
  rows = [],
  anchorDate = new Date()
) {
  if (timeRange === "All Time") return 0;

  const normalizedAnchorDate = createDashboardReportAnchorDate(anchorDate);
  const rowDates = rows
    .map((row) => parseDashboardReportDateValue(row.dateValue))
    .filter(Boolean)
    .sort((left, right) => left.getTime() - right.getTime());

  const earliestDate = rowDates[0] ?? normalizedAnchorDate;
  const daysAvailable = Math.max(
    0,
    Math.floor(
      (normalizedAnchorDate.getTime() - earliestDate.getTime()) /
      (1000 * 60 * 60 * 24)
    )
  );
  const rangeLength = getDashboardReportDateRangeLengthInDays(
    timeRange,
    customRange,
    anchorDate
  );

  if (!Number.isFinite(rangeLength)) return daysAvailable;

  if (timeRange === "Today") return 0;

  return Math.max(0, Math.min(daysAvailable, rangeLength - 1));
}

function getDashboardReportChartDateBounds(
  timeRange,
  customRange,
  rows = [],
  anchorDate = new Date()
) {
  const normalizedAnchorDate = createDashboardReportAnchorDate(anchorDate);
  const normalizedRange = normalizeDashboardReportDateRange(
    timeRange,
    customRange,
    anchorDate
  );
  const rowDates = rows
    .map((row) => parseDashboardReportDateValue(row.dateValue))
    .filter(Boolean)
    .sort((left, right) => left.getTime() - right.getTime());
  const earliestDate = rowDates[0] ?? normalizedAnchorDate;

  if (timeRange === "All Time") {
    return {
      start: earliestDate,
      end: normalizedRange.end ?? normalizedAnchorDate,
    };
  }

  return {
    start: normalizedRange.start ?? earliestDate,
    end: normalizedRange.end ?? normalizedAnchorDate,
  };
}

function getMonthDifference(start, end) {
  return (
    (end.getFullYear() - start.getFullYear()) * 12 +
    (end.getMonth() - start.getMonth())
  );
}

function getStartOfMonth(date) {
  return new Date(date.getFullYear(), date.getMonth(), 1);
}

function getEndOfMonth(date) {
  return new Date(date.getFullYear(), date.getMonth() + 1, 0);
}

function getStartOfYear(date) {
  return new Date(date.getFullYear(), 0, 1);
}

function getEndOfYear(date) {
  return new Date(date.getFullYear(), 11, 31);
}

function getDashboardReportTrendTabsForTimeRange(
  timeRange,
  customRange,
  anchorDate = new Date()
) {
  const rangeLength = getDashboardReportDateRangeLengthInDays(
    timeRange,
    customRange,
    anchorDate
  );
  if (timeRange === "All Time") {
    return SALES_SUMMARY_RANGE_TABS;
  }

  if (timeRange === "Last 30 Days") {
    return SALES_SUMMARY_RANGE_TABS.filter((tab) => tab.id !== "monthly");
  }

  if (timeRange === "Custom Date") {
    if (rangeLength <= 7) {
      return SALES_SUMMARY_RANGE_TABS.filter(
        (tab) => tab.id === "hourly" || tab.id === "shift" || tab.id === "daily"
      );
    }

    if (rangeLength <= 30) {
      return SALES_SUMMARY_RANGE_TABS.filter((tab) => tab.id !== "monthly");
    }

    return SALES_SUMMARY_RANGE_TABS;
  }

  return SALES_SUMMARY_RANGE_TABS.filter(
    (tab) => tab.id === "hourly" || tab.id === "shift" || tab.id === "daily"
  );
}

function getDashboardReportTrendWindow(
  rangeId,
  timeRange,
  customRange,
  rows = [],
  anchorDate = new Date(),
  offset = 0
) {
  const { start, end } = getDashboardReportChartDateBounds(
    timeRange,
    customRange,
    rows,
    anchorDate
  );
  const normalizedStart = createDashboardReportAnchorDate(start);
  const normalizedEnd = createDashboardReportAnchorDate(end);
  const normalizedOffset = Math.max(0, offset);
  const rangeLength = getDashboardReportDateRangeLengthInDays(
    timeRange,
    customRange,
    anchorDate
  );
  const today = createDashboardReportAnchorDate(anchorDate);

  if (rangeId === "hourly" || rangeId === "shift") {
    const navigationLimit = Math.max(
      0,
      Math.floor(
        (normalizedEnd.getTime() - normalizedStart.getTime()) /
        (1000 * 60 * 60 * 24)
      )
    );
    const targetDate = shiftDateByDays(
      normalizedEnd,
      -Math.min(normalizedOffset, navigationLimit)
    );

    return {
      anchorDate: targetDate,
      navigationLabel:
        targetDate.getTime() === today.getTime()
          ? "Today"
          : formatDashboardReportDate(targetDate),
      navigationLimit,
      rangeEnd: targetDate,
      rangeStart: targetDate,
    };
  }

  if (rangeId === "daily") {
    const shouldUseExactDateRange =
      timeRange === "Today" ||
      timeRange === "Last 7 Days" ||
      timeRange === "Last 30 Days" ||
      (timeRange === "Custom Date" &&
        Number.isFinite(rangeLength) &&
        rangeLength <= 31);

    if (shouldUseExactDateRange) {
      const navigationLimit = timeRange === "Today" ? 0 : 0;

      return {
        anchorDate: normalizedEnd,
        navigationLabel:
          normalizedEnd.getTime() === today.getTime()
            ? "Today"
            : formatDashboardReportDate(normalizedEnd),
        navigationLimit,
        rangeEnd: normalizedEnd,
        rangeStart: normalizedStart,
      };
    }
  }

  if (rangeId === "weekly") {
    const allowHistoricalMonths =
      timeRange === "All Time" ||
      (timeRange === "Custom Date" && Number.isFinite(rangeLength) && rangeLength > 30);
    const endMonth = getStartOfMonth(normalizedEnd);
    const startMonth = allowHistoricalMonths
      ? getStartOfMonth(normalizedStart)
      : endMonth;
    const navigationLimit = allowHistoricalMonths
      ? Math.max(0, getMonthDifference(startMonth, endMonth))
      : 0;
    const targetMonth = shiftDateByMonths(
      endMonth,
      -Math.min(normalizedOffset, navigationLimit)
    );
    const isCurrentMonth =
      targetMonth.getFullYear() === normalizedEnd.getFullYear() &&
      targetMonth.getMonth() === normalizedEnd.getMonth();

    return {
      anchorDate: isCurrentMonth ? normalizedEnd : getEndOfMonth(targetMonth),
      navigationLabel:
        normalizedOffset === 0 ? "This Month" : formatMonthYear(targetMonth),
      navigationLimit,
      rangeEnd: isCurrentMonth ? normalizedEnd : getEndOfMonth(targetMonth),
      rangeStart: getStartOfMonth(targetMonth),
    };
  }

  const allowHistoricalYears =
    timeRange === "All Time" ||
    (timeRange === "Custom Date" && Number.isFinite(rangeLength) && rangeLength > 365);
  const endYear = getStartOfYear(normalizedEnd);
  const startYear = allowHistoricalYears
    ? getStartOfYear(normalizedStart)
    : endYear;
  const navigationLimit = allowHistoricalYears
    ? Math.max(0, endYear.getFullYear() - startYear.getFullYear())
    : 0;
  const targetYear = new Date(
    endYear.getFullYear() - Math.min(normalizedOffset, navigationLimit),
    0,
    1
  );
  const isCurrentYear = targetYear.getFullYear() === normalizedEnd.getFullYear();

  return {
    anchorDate: isCurrentYear ? normalizedEnd : getEndOfYear(targetYear),
    navigationLabel:
      normalizedOffset === 0 ? "This Year" : String(targetYear.getFullYear()),
    navigationLimit,
    rangeEnd: isCurrentYear ? normalizedEnd : getEndOfYear(targetYear),
    rangeStart: getStartOfYear(targetYear),
  };
}

function getDashboardReportTrendNavigationLabel(
  rangeId,
  timeRange,
  customRange,
  rows = [],
  anchorDate = new Date(),
  offset = 0
) {
  return getDashboardReportTrendWindow(
    rangeId,
    timeRange,
    customRange,
    rows,
    anchorDate,
    offset
  ).navigationLabel;
}

function getDashboardReportTrendAnchorDateForOffset(
  rangeId,
  timeRange,
  customRange,
  rows = [],
  anchorDate = new Date(),
  offset = 0
) {
  return getDashboardReportTrendWindow(
    rangeId,
    timeRange,
    customRange,
    rows,
    anchorDate,
    offset
  ).anchorDate;
}

function createDashboardCatalogPerformanceRows(anchorDate = new Date()) {
  const today = createDashboardReportAnchorDate(anchorDate);
  const catalogs = [
    {
      id: "special-package",
      label: "Special Package",
      baseOrders: 18,
      grossPerOrder: 155000,
      discountRate: 0.042,
    },
    {
      id: "burger-supreme",
      label: "Burger Supreme",
      baseOrders: 14,
      grossPerOrder: 92000,
      discountRate: 0.035,
    },
    {
      id: "iced-coffee",
      label: "Iced Coffee",
      baseOrders: 20,
      grossPerOrder: 38000,
      discountRate: 0.028,
    },
    {
      id: "caesar-salad",
      label: "Caesar Salad",
      baseOrders: 9,
      grossPerOrder: 64000,
      discountRate: 0.031,
    },
    {
      id: "linguine-pesto",
      label: "Linguine Pesto",
      baseOrders: 8,
      grossPerOrder: 86000,
      discountRate: 0.034,
    },
    {
      id: "chicken-wrap",
      label: "Chicken Wrap",
      baseOrders: 11,
      grossPerOrder: 52000,
      discountRate: 0.029,
    },
  ];
  const shifts = ["Breakfast", "Lunch", "Tea", "Dinner"];
  const staffs = [
    "Natasha Smith",
    "Rendy Saputra",
    "Salsa Mahendra",
    "Dio Ramadhan",
    "Kevin Pratama",
  ];
  const orderTypes = ["Dine In", "Take Away", "Delivery", "Pickup"];

  return Array.from({ length: 45 }, (_, dayOffset) => {
    const date = shiftDateByDays(today, -dayOffset);
    const dateValue = formatDashboardReportDateValue(date);

    return catalogs.map((catalog, catalogIndex) => {
      const totalOrders =
        catalog.baseOrders +
        ((dayOffset + catalogIndex * 2) % 6) +
        (catalogIndex % 3);
      const grossSales =
        totalOrders * catalog.grossPerOrder +
        dayOffset * 4200 +
        catalogIndex * 6000;
      const discountValue = Math.round(
        grossSales *
        (catalog.discountRate + ((dayOffset + catalogIndex) % 3) * 0.004)
      );
      const netSales = grossSales - discountValue;

      return {
        id: `catalog-performance-${dateValue}-${catalog.id}`,
        date: formatDashboardReportDate(date),
        dateValue,
        catalog: catalog.label,
        shift: shifts[(dayOffset + catalogIndex) % shifts.length],
        staff: staffs[(dayOffset + catalogIndex * 2) % staffs.length],
        orderType: orderTypes[(dayOffset + catalogIndex) % orderTypes.length],
        totalOrdersValue: totalOrders,
        totalGrossSalesValue: grossSales,
        totalNetSalesValue: netSales,
        totalDiscountValue: discountValue,
        totalTaxValue: Math.round(netSales * 0.11),
        totalOrders: new Intl.NumberFormat("en-US").format(totalOrders),
        totalGrossSales: formatIdr(grossSales),
        totalNetSales: formatIdr(netSales),
        discountApplied: formatIdr(discountValue),
        taxCollected: formatIdr(Math.round(netSales * 0.11)),
      };
    });
  }).flat();
}

function getDashboardPerformanceTimeRangeMultiplier(timeRange, customRange) {
  if (timeRange === "Today") return 1;
  if (timeRange === "Last 7 Days") return 4;
  if (timeRange === "Last 30 Days") return 11;
  if (timeRange === "All Time") return 18;

  const start = parseDashboardReportDateValue(customRange.start);
  const end = parseDashboardReportDateValue(customRange.end);
  if (!start || !end) return 1;

  const normalizedStart = start.getTime() <= end.getTime() ? start : end;
  const normalizedEnd = start.getTime() <= end.getTime() ? end : start;
  const diffDays =
    Math.floor(
      (normalizedEnd.getTime() - normalizedStart.getTime()) /
      (1000 * 60 * 60 * 24)
    ) + 1;

  if (diffDays <= 1) return 1;
  if (diffDays <= 7) return 4;
  if (diffDays <= 30) return 11;
  return 18;
}

function getDashboardPerformanceTabsForTimeRange(tabs, timeRange, customRange) {
  const multiplier = getDashboardPerformanceTimeRangeMultiplier(
    timeRange,
    customRange
  );

  return tabs.map((tab) => ({
    ...tab,
    rows: tab.rows.map((row) => {
      const baseQty =
        row.qtyValue ??
        (Number(String(row.qty ?? "0").replace(/[^0-9]/g, "")) || 0);
      const baseRevenue =
        row.revenueValue ??
        (Number(String(row.revenue ?? "0").replace(/[^0-9]/g, "")) || 0);
      const qty = Math.max(1, Math.round(baseQty * multiplier));
      const revenue = Math.max(
        0,
        Math.round(
          baseRevenue * multiplier * (timeRange === "All Time" ? 0.92 : 1)
        )
      );

      return {
        ...row,
        qtyValue: baseQty,
        revenueValue: baseRevenue,
        qty: new Intl.NumberFormat("en-US").format(qty),
        revenue: formatIdr(revenue),
      };
    }),
  }));
}

function getDashboardSalesBreakdownSummaryForTimeRange(
  summary,
  timeRange,
  customRange
) {
  const multiplier = getDashboardPerformanceTimeRangeMultiplier(
    timeRange,
    customRange
  );
  const salesMultiplier = multiplier * (timeRange === "All Time" ? 0.92 : 1);
  const baseTotalSales =
    summary?.totalSalesValue ??
    (summary?.tabs || [])
      .find((tab) => tab.id === "item-revenue")
      ?.rows?.reduce((sum, row) => sum + (row.valueValue ?? 0), 0) ??
    0;
  const baseTotalOrders =
    summary?.totalOrdersValue ??
    (summary?.tabs || [])
      .find((tab) => tab.id === "item-qty")
      ?.rows?.reduce((sum, row) => sum + (row.valueValue ?? 0), 0) ??
    0;
  const totalSalesValue = Math.max(
    0,
    Math.round(baseTotalSales * salesMultiplier)
  );
  const totalOrdersValue = Math.max(
    0,
    Math.round(baseTotalOrders * multiplier)
  );

  return {
    ...summary,
    totalSalesValue,
    totalOrdersValue,
    totalSalesDisplayValue: formatIdr(totalSalesValue),
    totalOrdersDisplayValue: `${new Intl.NumberFormat("en-US").format(
      totalOrdersValue
    )} Orders`,
    tabs: (summary?.tabs || []).map((tab) => ({
      ...tab,
      rows: (tab.rows || []).map((row) => {
        const baseValue = row.valueValue ?? 0;
        const valueFormat = row.valueFormat ?? tab.valueFormat ?? "currency";
        const scaledValue = Math.max(
          0,
          Math.round(
            baseValue * (valueFormat === "qty" ? multiplier : salesMultiplier)
          )
        );

        return {
          ...row,
          valueValue: baseValue,
          scaledValue,
          displayValue:
            valueFormat === "qty"
              ? new Intl.NumberFormat("en-US").format(scaledValue)
              : new Intl.NumberFormat("id-ID").format(scaledValue),
        };
      }),
    })),
  };
}

function aggregateDashboardReportRowsByCatalog(rows, reportId) {
  const groupedRows = new Map();

  rows.forEach((row) => {
    const current = groupedRows.get(row.catalog) ?? {
      id: row.catalog.toLowerCase().replace(/\s+/g, "-"),
      catalog: row.catalog,
      totalOrdersValue: 0,
      discountAppliedValue: 0,
      taxCollectedValue: 0,
      totalGrossSalesValue: 0,
      totalNetSalesValue: 0,
    };

    current.totalOrdersValue += row.totalOrdersValue;
    current.discountAppliedValue += row.discountAppliedValue ?? 0;
    current.taxCollectedValue += row.taxCollectedValue ?? 0;
    current.totalGrossSalesValue += row.totalGrossSalesValue;
    current.totalNetSalesValue += row.totalNetSalesValue;
    groupedRows.set(row.catalog, current);
  });

  return Array.from(groupedRows.values())
    .map((row) => ({
      ...row,
      totalOrders: new Intl.NumberFormat("en-US").format(row.totalOrdersValue),
      discountApplied: formatIdr(row.discountAppliedValue),
      taxCollected: formatIdr(row.taxCollectedValue),
      totalGrossSales: formatIdr(row.totalGrossSalesValue),
      totalNetSales: formatIdr(row.totalNetSalesValue),
    }))
    .sort((left, right) =>
      reportId === "total-orders"
        ? right.totalOrdersValue - left.totalOrdersValue
        : right.totalNetSalesValue - left.totalNetSalesValue
    );
}

function getDashboardReportAggregateMeta(detailView) {
  switch (detailView) {
    case "by-business-unit":
      return { key: "businessUnit", label: "Entity" };
    case "by-category":
      return { key: "category", label: "Category" };
    case "by-modifier":
      return { key: "modifier", label: "Modifier" };
    case "by-order-type":
      return { key: "orderType", label: "Order Type" };
    case "by-table":
      return { key: "table", label: "Table" };
    case "by-staff":
      return { key: "staff", label: "Staff" };
    case "by-payment-method":
      return { key: "payment", label: "Payment Method" };
    case "by-item":
    default:
      return { key: "catalog", label: "Catalog" };
  }
}

function aggregateDashboardReportRows(rows, detailView, reportId) {
  const aggregateMeta = getDashboardReportAggregateMeta(detailView);
  const groupedRows = new Map();

  rows.forEach((row) => {
    const groupValue = row[aggregateMeta.key] ?? "-";
    const current = groupedRows.get(groupValue) ?? {
      id: `${aggregateMeta.key}-${String(groupValue)
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "-")}`,
      groupLabel: groupValue,
      totalOrdersValue: 0,
      discountAppliedValue: 0,
      taxCollectedValue: 0,
      totalGrossSalesValue: 0,
      totalNetSalesValue: 0,
    };

    current.totalOrdersValue += row.totalOrdersValue ?? 0;
    current.discountAppliedValue += row.discountAppliedValue ?? 0;
    current.taxCollectedValue += row.taxCollectedValue ?? 0;
    current.totalGrossSalesValue += row.totalGrossSalesValue ?? 0;
    current.totalNetSalesValue += row.totalNetSalesValue ?? 0;
    groupedRows.set(groupValue, current);
  });

  return Array.from(groupedRows.values())
    .map((row) => ({
      ...row,
      totalOrders: new Intl.NumberFormat("en-US").format(row.totalOrdersValue),
      discountApplied: formatIdr(row.discountAppliedValue),
      taxCollected: formatIdr(row.taxCollectedValue),
      totalGrossSales: formatIdr(row.totalGrossSalesValue),
      totalNetSales: formatIdr(row.totalNetSalesValue),
    }))
    .sort((left, right) =>
      reportId === "total-orders"
        ? right.totalOrdersValue - left.totalOrdersValue
        : right.totalNetSalesValue - left.totalNetSalesValue
    );
}

