  function clearCatalogDraftError(...keys) {
    setCatalogDraftErrors((previous) => {
      const next = { ...previous };
      let hasChanges = false;

      keys.forEach((key) => {
        if (next[key]) {
          delete next[key];
          hasChanges = true;
        }
      });

      return hasChanges ? next : previous;
    });
  }

